-- VoiceTask schema. Apply with Supabase CLI to a dedicated project.
create extension if not exists pgcrypto;
create type public.task_category as enum ('Crying Voice','Angry Voice','Sad Voice','Happy Voice','Commercial Voice','Excited Voice');
create type public.task_state as enum ('draft','published','paused','archived');
create type public.assignment_state as enum ('assigned','in_progress','submitted','quality_review','approved','rejected','needs_rerecord');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',public_display_name text,country text not null default 'GB' check(country in ('GB','US','FR','IT')),mobile_e164 text,email_display text,timezone text not null default 'UTC',status text not null default 'active' check(status in ('active','suspended','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('member','admin','reviewer','support')),granted_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(user_id,role));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles r where r.user_id=(select auth.uid()) and r.role='admin')$$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
create table public.user_settings(user_id uuid primary key references auth.users(id) on delete cascade,in_app_notifications boolean not null default true,email_notifications boolean not null default true,whatsapp_opt_in boolean not null default false,whatsapp_verified_at timestamptz,locale text not null default 'en-GB',timezone text not null default 'UTC');
create table public.consent_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),policy_version text not null, data_use_purpose text not null, choice boolean not null,legal_basis text not null,accepted_at timestamptz not null default now(),ip_hash text);
create table public.invitation_tokens(id uuid primary key default gen_random_uuid(),token_hash text not null unique,issued_by_user uuid references auth.users(id),expires_at timestamptz,max_uses int not null default 1 check(max_uses between 1 and 100),uses int not null default 0 check(uses>=0),revoked_at timestamptz,created_at timestamptz not null default now(),check(uses<=max_uses));
create table public.invitation_redemptions(token_id uuid not null references public.invitation_tokens(id),user_id uuid not null references auth.users(id),redeemed_at timestamptz not null default now(),primary key(token_id,user_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),title text not null check(length(trim(title))>0),description text,category public.task_category not null,reward_pence bigint not null check(reward_pence>0),status public.task_state not null default 'draft',version int not null default 1,language text not null default 'en-GB',instructions text,estimated_minutes integer,published_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index on public.tasks(category,status,published_at);
create table public.task_phrases(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,position int not null check(position between 1 and 70),expected_text text not null check(length(trim(expected_text))>0),duration_min_seconds int not null default 1,duration_max_seconds int not null default 120,unique(task_id,position),check(duration_min_seconds>0 and duration_max_seconds>=duration_min_seconds));
create table public.user_task_assignments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),task_id uuid not null references public.tasks(id),category_snapshot public.task_category not null,reward_pence_snapshot bigint not null check(reward_pence_snapshot>0),task_version_snapshot int not null,assigned_at timestamptz not null default now(),status public.assignment_state not null default 'assigned',unique(user_id,task_id));
create index on public.user_task_assignments(user_id,category_snapshot,status,assigned_at);
create table public.assignment_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),category public.task_category not null,entitlement_slot int not null,task_id uuid not null references public.tasks(id),allocated_at timestamptz not null default now(),unique(user_id,category,entitlement_slot));
create table public.task_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.user_task_assignments(id),user_id uuid not null references auth.users(id),submitted_at timestamptz not null default now(),status text not null default 'submitted' check(status in ('submitted','quality_review','manual_review','approved','rejected','needs_rerecord')),review_due_at timestamptz not null default (now()+interval '5 minutes'),approved_at timestamptz,rejected_at timestamptz,review_reason text,approved_duration_ms bigint not null default 0 check(approved_duration_ms>=0),validator_version text,idempotency_key uuid not null unique);
create index on public.task_submissions(status,review_due_at);
create table public.recording_drafts(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.user_task_assignments(id),user_id uuid not null references auth.users(id),phrase_id uuid not null references public.task_phrases(id),storage_path text not null,byte_size bigint not null check(byte_size>0),mime_type text not null,created_at timestamptz not null default now(),unique(assignment_id,phrase_id),unique(storage_path));
create table public.recording_files(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.task_submissions(id),phrase_id uuid not null references public.task_phrases(id),path text not null,mime_type text not null,byte_size bigint not null,checksum_sha256 text,duration_ms bigint,voice_seconds_ms bigint,quality_state text not null default 'pending',created_at timestamptz not null default now(),unique(submission_id,phrase_id));
create table public.audio_quality_results(recording_id uuid primary key references public.recording_files(id),checks jsonb not null default '{}',validator_version text not null,final_decision text not null check(final_decision in ('passed','failed','manual_review')),score numeric(5,2),checked_at timestamptz not null default now());
create table public.wallet_accounts(user_id uuid primary key references auth.users(id),currency text not null default 'GBP' check(currency='GBP'),available_pence bigint not null default 0 check(available_pence>=0),reserved_pence bigint not null default 0 check(reserved_pence>=0),liability_ledger_version bigint not null default 0);
create table public.wallet_ledger_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount_pence bigint not null check(amount_pence<>0),currency text not null default 'GBP' check(currency='GBP'),entry_type text not null,source_type text not null,source_id uuid not null,effect_type text not null,idempotency_key text not null unique,created_at timestamptz not null default now(),created_by uuid references auth.users(id),reason text,unique(source_type,source_id,effect_type));
create index on public.wallet_ledger_entries(user_id,created_at desc);
create table public.payout_destinations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),type text not null check(type in ('paypal','bank')),provider_token_ref text not null,verified boolean not null default false,masked_display text not null,country text not null,created_at timestamptz not null default now());
create table public.withdrawal_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),requested_pence bigint not null check(requested_pence>=25000),fee_pence bigint not null default 0 check(fee_pence>=0),destination_id uuid not null references public.payout_destinations(id),provider text not null,status text not null default 'requested' check(status in ('requested','under_review','approved','processing','paid','rejected','failed','cancelled')),provider_reference text,rejection_reason text,requested_at timestamptz not null default now(),resolved_at timestamptz,approved_by uuid references auth.users(id),idempotency_key uuid not null unique);
create index on public.withdrawal_requests(status,requested_at desc);
create table public.identity_verifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),status text not null default 'submitted' check(status in ('not_started','submitted','processing','manual_review','verified','rejected','expired')),submitted_at timestamptz not null default now(),due_at timestamptz not null default(now()+interval '168 hours'),resolved_at timestamptz,provider text,provider_reference text,reviewer uuid references auth.users(id),decision_reason text);
create index on public.identity_verifications(status,due_at);
create table public.identity_documents(id uuid primary key default gen_random_uuid(),verification_id uuid not null references public.identity_verifications(id),storage_path text not null unique,doc_type text not null,side text default 'front',created_at timestamptz not null default now(),retention_expiry timestamptz);
create table public.identity_status_events(id uuid primary key default gen_random_uuid(),verification_id uuid references public.identity_verifications(id),from_status text,to_status text not null,source text not null,actor uuid references auth.users(id),at timestamptz not null default now(),reason text);
create table public.verification_access_logs(id uuid primary key default gen_random_uuid(),verification_id uuid references public.identity_verifications(id),actor uuid references auth.users(id),action text not null,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),title text not null,body text not null,type text not null default 'information',read_at timestamptz,created_at timestamptz not null default now(),deep_link text);
create index on public.notifications(user_id,read_at);
create table public.broadcasts(id uuid primary key default gen_random_uuid(),title text not null,body text not null,audience_filter jsonb not null default '{"kind":"all"}',type text not null default 'information',starts_at timestamptz not null default now(),ends_at timestamptz not null,status text not null default 'draft' check(status in ('draft','published','paused','archived')),created_by uuid not null default auth.uid() references auth.users(id));
create index on public.broadcasts(status,starts_at,ends_at);
create table public.broadcast_impressions(broadcast_id uuid not null references public.broadcasts(id),user_id uuid not null references auth.users(id),auth_session_identifier uuid not null,shown_at timestamptz not null default now(),primary key(broadcast_id,user_id,auth_session_identifier));
create table public.leaderboard_adjustments(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),period_scope text not null,bonus_points int not null,reason text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.rank_history(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),from_level text,to_level text not null,approved_seconds_at_change bigint not null,created_at timestamptz not null default now());
create table public.daily_recording_summary(user_id uuid not null references auth.users(id),local_date date not null,uploaded_seconds bigint not null default 0,approved_seconds bigint not null default 0,qualifying_streak_day boolean not null default false,primary key(user_id,local_date));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references auth.users(id),action text not null,entity_type text,entity_id uuid,before_filtered jsonb,after_filtered jsonb,ip_hash text,created_at timestamptz not null default now());
create table public.support_tickets(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),subject text not null,status text not null default 'open',admin_assignee uuid references auth.users(id),created_at timestamptz not null default now());
create table public.support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid references public.support_tickets(id),sender_id uuid references auth.users(id),body text not null,created_at timestamptz not null default now());
create table public.system_settings(key text primary key,value jsonb not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.partner_exports(id uuid primary key default gen_random_uuid(),dataset_id uuid,recording_ids uuid[],export_status text not null default 'pending',partner_reference text,export_timestamp timestamptz,lawful_basis text,contractual_usage_scope text);
create table public.cron_job_runs(id uuid primary key default gen_random_uuid(),job_name text not null,status text not null,retry_count int not null default 0,error_message text,started_at timestamptz not null default now(),finished_at timestamptz);
-- New user records are created by Auth triggers only; public signup must be disabled for production.
create or replace function public.init_member() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.profiles(id,full_name,email_display,country,mobile_e164) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email,coalesce(new.raw_user_meta_data->>'country','GB'),new.raw_user_meta_data->>'mobile') on conflict do nothing;
 insert into public.user_settings(user_id) values(new.id) on conflict do nothing;
 insert into public.wallet_accounts(user_id) values(new.id) on conflict do nothing;
 insert into public.user_roles(user_id,role) values(new.id,'member') on conflict do nothing;
 return new;
end $$;
create trigger on_member_created after insert on auth.users for each row execute function public.init_member();
-- Explicitly enable RLS on every client-visible table; denied by default without a policy.
do $$declare t text;begin
 foreach t in array array['profiles','user_roles','user_settings','consent_records','invitation_tokens','invitation_redemptions','tasks','task_phrases','user_task_assignments','assignment_events','task_submissions','recording_drafts','recording_files','audio_quality_results','wallet_accounts','wallet_ledger_entries','payout_destinations','withdrawal_requests','identity_verifications','identity_documents','identity_status_events','verification_access_logs','notifications','broadcasts','broadcast_impressions','leaderboard_adjustments','rank_history','daily_recording_summary','audit_logs','support_tickets','support_messages','system_settings','partner_exports','cron_job_runs']
 loop execute format('alter table public.%I enable row level security',t);end loop;
end $$;
create policy "own profiles or admin" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin());
create policy "own profile update" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
-- UPDATE rights are column-scoped, so clients cannot alter legal status or country.
revoke update on public.profiles from authenticated;
grant update(full_name,public_display_name,mobile_e164,timezone) on public.profiles to authenticated;
create policy "settings owner" on public.user_settings for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "settings owner update" on public.user_settings for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke update on public.user_settings from authenticated;
grant update(in_app_notifications,email_notifications,whatsapp_opt_in,locale,timezone) on public.user_settings to authenticated;
create policy "roles visible to owner" on public.user_roles for select to authenticated using(user_id=(select auth.uid()));
create policy "published tasks" on public.tasks for select to authenticated using(status='published' or public.is_admin());
create policy "published phrases" on public.task_phrases for select to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and (t.status='published' or public.is_admin())));
create policy "my assignments" on public.user_task_assignments for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my submissions" on public.task_submissions for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my drafts" on public.recording_drafts for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my recording metadata" on public.recording_files for select to authenticated using(exists(select 1 from public.task_submissions s where s.id=submission_id and (s.user_id=(select auth.uid()) or public.is_admin())));
create policy "my wallet" on public.wallet_accounts for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my wallet ledger" on public.wallet_ledger_entries for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my destinations" on public.payout_destinations for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my withdrawals" on public.withdrawal_requests for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my verification" on public.identity_verifications for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "admin private documents" on public.identity_documents for select to authenticated using(public.is_admin());
create policy "my notifications" on public.notifications for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my notifications mark read" on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke update on public.notifications from authenticated; grant update(read_at) on public.notifications to authenticated;
create policy "active broadcasts" on public.broadcasts for select to authenticated using((status='published' and starts_at<=now() and ends_at>now()) or public.is_admin());
create policy "admin broadcasts" on public.broadcasts for insert to authenticated with check(public.is_admin());
create policy "admin broadcast updates" on public.broadcasts for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "my impressions" on public.broadcast_impressions for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "my impressions insert" on public.broadcast_impressions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.broadcasts b where b.id=broadcast_id and b.status='published' and b.starts_at<=now() and b.ends_at>now()));
create policy "my support" on public.support_tickets for select to authenticated using(owner_id=(select auth.uid()) or public.is_admin());
create policy "my support create" on public.support_tickets for insert to authenticated with check(owner_id=(select auth.uid()));
create policy "my support messages" on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and(t.owner_id=(select auth.uid()) or public.is_admin())));
create policy "admin audit" on public.audit_logs for select to authenticated using(public.is_admin());
create policy "admin tasks" on public.tasks for insert to authenticated with check(public.is_admin());
create policy "admin tasks update" on public.tasks for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin phrase editing" on public.task_phrases for insert to authenticated with check(public.is_admin());
create policy "admin settings" on public.system_settings for select to authenticated using(public.is_admin());
create policy "admin verifications" on public.identity_status_events for select to authenticated using(public.is_admin());
create policy "admin exports" on public.partner_exports for select to authenticated using(public.is_admin());
-- Financial and role tables are intentionally not directly writable by clients.
revoke insert,update,delete on public.wallet_accounts,public.wallet_ledger_entries,public.user_roles,public.task_submissions,public.user_task_assignments,public.identity_verifications,public.identity_documents,public.withdrawal_requests,public.payout_destinations,public.assignment_events,public.recording_drafts,public.recording_files,public.audio_quality_results from authenticated,anon;
-- No direct storage uploads: only server-generated signed tokens.
insert into storage.buckets(id,name,public,file_size_limit) values('voice-recordings','voice-recordings',false,26214400),('identity-documents','identity-documents',false,10485760) on conflict(id) do nothing;
-- No storage.objects client read/list policy. Downloads are short-lived signed URLs issued by privileged functions only.
